// Copies science bundles into public/bundles/ and writes public/bundles/index.json.
// Sources, in priority order:
//   1. ../data/bundles/*.json          (science branch output; fixture.json first)
//   1b. ../data/viewer/*.json          (science branch export in POLARIS-X5D-v2 + derived, e.g. the ROI datasets)
//   2. ../app/data/polaris-source-*-v2.json (Codex source cases; raw inputs only)
//   3. public/bundles/demo-fixture.json (DEMO, generated by scripts/make_demo_fixture.py)
// The viewer never edits a bundle. It only lists what exists.
import { createHash } from 'node:crypto';
import { copyFileSync, existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { basename, dirname, join, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const web = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const repo = resolve(web, '..');
const out = join(web, 'public', 'bundles');
mkdirSync(out, { recursive: true });

const entries = [];
function add(src, origin) {
  const name = basename(src);
  const dest = join(out, name);
  if (resolve(src) !== resolve(dest)) copyFileSync(src, dest);
  const bytes = readFileSync(dest);
  let status = 'UNKNOWN';
  let label = name;
  try {
    const j = JSON.parse(bytes.toString('utf8'));
    if (j?.schema === 'science-bundle-v2' || j?.schema === 'polaris-science-results-v1') {
      // Person A's format (a-science): one site per bundle
      status = j?.validation_status?.overall ?? status;
      label = `${j?.site?.name ?? j?.bundle_id} · ${j.schema} — ${name}`;
    } else {
      status = j?.validation?.status ?? status;
      const names = (j?.datasets ?? []).map((d) => d?.site?.name ?? d?.siteId);
      label = `${names.join(' + ')} — ${name}`;
    }
  } catch {
    status = 'UNREADABLE';
  }
  entries.push({ file: name, origin, status, label, sha256: createHash('sha256').update(bytes).digest('hex'), bytes: bytes.length });
}

const sci = join(repo, 'data', 'bundles');
if (existsSync(sci)) {
  const files = readdirSync(sci).filter((f) => f.endsWith('.json')).sort((a, b) => (a === 'fixture.json' ? -1 : b === 'fixture.json' ? 1 : a.localeCompare(b)));
  for (const f of files) add(join(sci, f), 'data/bundles (science branch)');
}
const viewerData = join(repo, 'data', 'viewer');
if (existsSync(viewerData)) {
  for (const f of readdirSync(viewerData).filter((f) => f.endsWith('.json')).sort()) add(join(viewerData, f), 'data/viewer (science branch export with derived)');
}
const appData = join(repo, 'app', 'data');
if (existsSync(appData)) {
  for (const f of readdirSync(appData).filter((f) => /^polaris-source-.*-v2\.json$/.test(f)).sort()) add(join(appData, f), 'app/data (Codex source case)');
}
const demo = join(out, 'demo-fixture.json');
if (existsSync(demo)) add(demo, 'DEMO fixture (synthetic)');
const demoDecision = join(out, 'demo-decision-fixture.json');
if (existsSync(demoDecision)) add(demoDecision, 'DEMO decision-evidence fixture (synthetic A1–A4; scripts/make_decision_fixture.py)');

// DISPLAY-ONLY assets (never science inputs): terrain context packs and registered visual layers.
//   ../data/visual/terrain_context/<datasetId>/*  -> public/context/<datasetId>/   (tools/terrain/build_terrain_context.py)
//   ../data/visual/visual_layers.json + its PNGs  -> public/visual/                (tools/sources/build_visual_layers.py)
const ctxSrc = join(repo, 'data', 'visual', 'terrain_context');
const copied = { context: [], visual: [] };
if (existsSync(ctxSrc)) {
  for (const id of readdirSync(ctxSrc).sort()) {
    if (!existsSync(join(ctxSrc, id, 'context.json'))) continue;
    mkdirSync(join(web, 'public', 'context', id), { recursive: true });
    for (const f of readdirSync(join(ctxSrc, id))) copyFileSync(join(ctxSrc, id, f), join(web, 'public', 'context', id, f));
    copied.context.push(id);
  }
}
const layersFile = join(repo, 'data', 'visual', 'visual_layers.json');
if (existsSync(layersFile)) {
  const doc = JSON.parse(readFileSync(layersFile, 'utf8'));
  mkdirSync(join(web, 'public', 'visual'), { recursive: true });
  for (const l of doc.layers ?? []) {
    const src = join(repo, l.artifact.path);
    const bytes = readFileSync(src);
    if (createHash('sha256').update(bytes).digest('hex') !== l.artifact.sha256) throw new Error(`visual layer ${l.id}: artifact hash differs from visual_layers.json`);
    copyFileSync(src, join(web, 'public', 'visual', basename(src)));
    copied.visual.push(l.id);
  }
  copyFileSync(layersFile, join(web, 'public', 'visual', 'visual_layers.json'));
}
// Global Moon (visual context): the compact NASA SVS 14959 GLB, hash-pinned (docs/DATA_PROVENANCE.md)
const moonSrc = join(repo, 'app', 'assets', 'nasa', 'NASA_SVS_moon_small.glb');
if (existsSync(moonSrc)) {
  const bytes = readFileSync(moonSrc);
  if (createHash('sha256').update(bytes).digest('hex') !== '12d3b0bb7fe214903f51447d1bc61710f442e92a11c703fcaca6d4e7ff8e67d4') throw new Error('NASA_SVS_moon_small.glb: SHA-256 differs from the documented value');
  mkdirSync(join(web, 'public', 'globe'), { recursive: true });
  copyFileSync(moonSrc, join(web, 'public', 'globe', 'NASA_SVS_moon_small.glb'));
}
console.log(`display-only: context packs [${copied.context.join(', ') || 'none'}], visual layers [${copied.visual.join(', ') || 'none'}]`);

// the demo hero case opens first when present (Site04 ROI3, 1 m mast: the ridge-of-record story)
const hero = entries.findIndex((e) => e.file === 'site04_roi3_2026-11-14_14d_mast1m.json');
if (hero > 0) entries.unshift(...entries.splice(hero, 1));
writeFileSync(join(out, 'index.json'), JSON.stringify({ generated: new Date().toISOString(), bundles: entries }, null, 2));
console.log(`bundles: ${entries.map((e) => `${e.file} [${e.status}]`).join(', ') || 'none'}`);
